class Solution {
public:
    int numberOfWays(int n, int x) {
        int mod = 1e9 + 7;
        vector<int> dp(n + 1, 0);
        dp[0] = 1;
        int base = 1;
        while (true) {
            long long val = 1;
            for (int i = 0; i < x; ++i) {
                val *= base;
                if (val > n) break;
            }
            if (val > n) break;
            for (int s = n; s >= val; --s) {
                dp[s] = (dp[s] + dp[s - val]) % mod;
            }
            base++;
        }
        return dp[n];
    }
};

class Solution {
    public int numberOfWays(int n, int x) {
        int mod = 1_000_000_007;
        int[] dp = new int[n + 1];
        dp[0] = 1;
        int base = 1;
        while (true) {
            long val = 1;
            for (int i = 0; i < x; i++) {
                val *= base;
                if (val > n) break;
            }
            if (val > n) break;
            int intVal = (int) val;
            for (int s = n; s >= intVal; s--) {
                dp[s] = (dp[s] + dp[s - intVal]) % mod;
            }
            base++;
        }
        return dp[n];
    }
}

