var numberOfWays = function(n, x) {
    const mod = 1000000007;
    const dp = new Array(n + 1).fill(0);
    dp[0] = 1;
    let base = 1;
    while (true) {
        const val = Math.pow(base, x);
        if (val > n) break;
        for (let s = n; s >= val; s--) {
            dp[s] = (dp[s] + dp[s - val]) % mod;
        }
        base++;
    }
    return dp[n];
};
